    26	/**
    27	 * Retrieves the characters from the specified cursor position up to the next space or new line.
    28	 *
    29	 * @param inputString - The input string.
    30	 * @param cursorPosition - The position of the cursor within the input string.
    31	 * @returns - The substring from the cursor position up to the next space or new line.
    32	 *                     If no space or new line is found, returns the substring from the cursor position to the end of the input string.
    33	 */
    34	const getNextChars = (inputString: string, cursorPosition: number): string => {
    35	    // Get the substring starting from the cursor position
    36	    const subString = inputString.substring(cursorPosition);
    37	
    38	    // Find the index of the next space or new line character
    39	    const spaceIndex = subString.search(/[ \n]/);
    40	
    41	    if (spaceIndex === -1) {
    42	        return subString;
    43	    }
    44	
    45	    // If there is a space or new line, return the substring up to the space or new line
    46	    return subString.substring(0, spaceIndex);
    47	};
